  GlobalChunkCoordinate3D chunk{};
  constexpr auto operator<=>(const WorldDeltaChunkKey3D &) const = default;
};
struct WorldChunkBaseRevision3D {
  std::uint64_t generatorId{}, generatorVersion{}, worldSeed{},
      contentRevision{};
